begin;

-- order-cancel-and-cancelled-view (T2, level A): whole-order cancellation and the "Canceladas" reader.
--
-- Rules (S6 section 5.1 decisions 1-6, Emmanuel 2026-10-01 "Sin venta" = "Cancelar"):
--   * only owner/admin/manager/supervisor (permission orders.cancel.order) cancel a whole order, with a mandatory reason
--     of 1..200 characters; the supervisor authorization is generated by the server from the authenticated actor.
--   * allowed from draft|open|partially_paid|paid. closed and cancelled are terminal. Delivered lines make it impossible.
--   * an order whose delivery is `assigned|en_route` is never cancelled (DELIVERY_ACTIVE): the courier must mark it
--     failed or it must be settled first.
--   * money already captured never blocks: the order is cancelled and an immutable obligation to return it is recorded
--     (`refund_obligation_status = pending`). There is no refund yet; the obligation is the only financial record.
--   * every line already sent to the kitchen gets its own audit event and KDS `cancelled` correction.
--   * the whole command is one transaction with command-level idempotency (same actor/scope/key and byte-identical
--     payload replays the stored result; any divergence is a conflict).
-- The aggregate steps are computed by the API from the pure domain (`cancelOrder`); this function re-verifies every
-- structural invariant before persisting, as `persist_order_item_cancellation` does for a single line.

alter table app.order_command_events drop constraint order_command_events_kind_valid;
alter table app.order_command_events add constraint order_command_events_kind_valid
  check (command_kind in ('send_to_kitchen','cancel_order'));

create table app.order_cancellations (
  restaurant_id uuid not null,
  branch_id uuid not null,
  order_id uuid not null,
  event_id uuid not null,
  from_status text not null,
  result_version bigint not null,
  reason text not null,
  actor_id uuid not null references auth.users (id) on delete restrict,
  device_id uuid not null,
  occurred_at timestamptz not null,
  received_at timestamptz not null default pg_catalog.clock_timestamp(),
  refund_obligation_status text not null,
  captured_minor bigint not null,
  captured_tip_minor bigint not null,
  currency text not null,
  constraint order_cancellations_pk primary key (restaurant_id, branch_id, order_id),
  constraint order_cancellations_order_fk foreign key (restaurant_id, branch_id, order_id)
    references app.orders (restaurant_id, branch_id, id) on delete restrict,
  constraint order_cancellations_event_unique unique (event_id),
  constraint order_cancellations_from_valid check (from_status in ('draft','open','partially_paid','paid')),
  constraint order_cancellations_reason_valid check (
    reason = pg_catalog.btrim(reason) and pg_catalog.char_length(reason) between 1 and 200 and reason !~ '[[:cntrl:]]'
  ),
  constraint order_cancellations_obligation_valid check (refund_obligation_status in ('none','pending')),
  constraint order_cancellations_money_valid check (
    captured_minor between 0 and 9007199254740991 and captured_tip_minor between 0 and 9007199254740991
    and currency ~ '^[A-Z]{3}$'
    and (refund_obligation_status = 'pending' or (captured_minor = 0 and captured_tip_minor = 0))
    and (from_status not in ('partially_paid','paid') or refund_obligation_status = 'pending')
  ),
  constraint order_cancellations_version_valid check (result_version between 2 and 9007199254740991)
);

create index order_cancellations_branch_received_idx
  on app.order_cancellations (restaurant_id, branch_id, received_at desc, order_id);

alter table app.order_cancellations enable row level security;
alter table app.order_cancellations force row level security;
revoke all on app.order_cancellations from public, anon, authenticated, service_role, app_api;

create function app_private.reject_order_cancellation_change() returns trigger
language plpgsql set search_path = '' as $function$
begin
  raise exception using errcode = '55000', message = 'ORDER_CANCELLATION_IMMUTABLE';
end
$function$;

create trigger order_cancellations_immutable
  before update or delete on app.order_cancellations
  for each row execute function app_private.reject_order_cancellation_change();

create function app_private.cancel_order(p_actor_id uuid, p_command jsonb, p_steps jsonb)
returns jsonb language plpgsql volatile security definer set search_path = '' as $function$
declare
  v_restaurant uuid;
  v_branch uuid;
  v_order_id uuid;
  v_event uuid;
  v_device uuid;
  v_expected bigint;
  v_occurred timestamptz;
  v_key text;
  v_reason text;
  v_existing app.order_command_events%rowtype;
  v_current app.orders%rowtype;
  v_start_status text;
  v_delivery_state text;
  v_captured bigint;
  v_captured_tip bigint;
  v_obligation text;
  v_count integer;
  v_index integer;
  v_step jsonb;
  v_order jsonb;
  v_audit jsonb;
  v_step_event uuid;
  v_step_key text;
  v_item_id uuid;
  v_old_item jsonb;
  v_new_item jsonb;
  v_old_status text;
  v_expected_pending jsonb;
  v_received timestamptz;
  v_cursor bigint;
  v_station text;
  v_kds_events jsonb := '[]'::jsonb;
  v_authorization jsonb;
  v_result jsonb;
begin
  if p_actor_id is null or pg_catalog.jsonb_typeof(p_command) <> 'object' or pg_catalog.jsonb_typeof(p_steps) <> 'array'
    or not app_private.jsonb_has_exact_keys(p_command, array[
      'schemaVersion','scope','orderId','expectedVersion','eventId','idempotencyKey','deviceId','occurredAt','reason'])
    or not app_private.jsonb_has_exact_keys(p_command -> 'scope', array['restaurantId','branchId'])
    or p_command -> 'schemaVersion' is distinct from '1'::jsonb
    or pg_catalog.jsonb_typeof(p_command -> 'expectedVersion') is distinct from 'number'
    or not coalesce(p_command ->> 'expectedVersion' ~ '^[1-9][0-9]*$', false)
    or pg_catalog.jsonb_typeof(p_command -> 'reason') is distinct from 'string'
  then return pg_catalog.jsonb_build_object('status','conflict'); end if;
  begin
    v_restaurant := (p_command #>> '{scope,restaurantId}')::uuid;
    v_branch := (p_command #>> '{scope,branchId}')::uuid;
    v_order_id := (p_command ->> 'orderId')::uuid;
    v_event := (p_command ->> 'eventId')::uuid;
    v_device := (p_command ->> 'deviceId')::uuid;
    v_expected := (p_command ->> 'expectedVersion')::bigint;
    v_occurred := (p_command ->> 'occurredAt')::timestamptz;
  exception when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow
    or invalid_datetime_format then
    return pg_catalog.jsonb_build_object('status','conflict');
  end;
  v_key := p_command ->> 'idempotencyKey';
  v_reason := p_command ->> 'reason';
  if v_key is null or v_key <> pg_catalog.btrim(v_key) or pg_catalog.char_length(v_key) not between 1 and 200
    or v_key ~ '[[:cntrl:]]'
    or v_reason <> pg_catalog.btrim(v_reason) or pg_catalog.char_length(v_reason) not between 1 and 200
    or v_reason ~ '[[:cntrl:]]'
    or p_command ->> 'occurredAt' is distinct from
      pg_catalog.to_char(v_occurred at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  then return pg_catalog.jsonb_build_object('status','conflict'); end if;

  if not exists (
    select 1 from app.memberships m
    join app.membership_role_grants g on g.membership_id = m.id and g.revoked_at is null
      and g.role_code in ('owner','admin','manager','supervisor')
    join app.restaurants r on r.id = m.restaurant_id and r.disabled_at is null
    join app.branches b on b.id = m.branch_id and b.restaurant_id = m.restaurant_id and b.disabled_at is null
    where m.user_id = p_actor_id and m.restaurant_id = v_restaurant and m.branch_id = v_branch and m.revoked_at is null
  ) then return pg_catalog.jsonb_build_object('status','forbidden'); end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('order:' || v_order_id::text, 0));

  select * into v_existing from app.order_command_events
  where actor_id = p_actor_id and restaurant_id = v_restaurant and branch_id = v_branch and idempotency_key = v_key;
  if found then
    if v_existing.command_kind <> 'cancel_order' or v_existing.command_payload <> p_command
    then return pg_catalog.jsonb_build_object('status','conflict'); end if;
    return pg_catalog.jsonb_set(v_existing.result, '{status}', '"replayed"'::jsonb);
  end if;
  if exists (select 1 from app.order_audit_events where event_id = v_event)
    or exists (select 1 from app.order_command_events where event_id = v_event)
  then return pg_catalog.jsonb_build_object('status','conflict'); end if;

  select * into v_current from app.orders
  where restaurant_id = v_restaurant and branch_id = v_branch and id = v_order_id for update;
  if not found or v_current.version <> v_expected
    or v_current.status not in ('draft','open','partially_paid','paid')
  then return pg_catalog.jsonb_build_object('status','conflict'); end if;
  v_start_status := v_current.status;

  select state into v_delivery_state from app.order_deliveries
  where restaurant_id = v_restaurant and branch_id = v_branch and order_id = v_order_id;
  if v_delivery_state in ('assigned','en_route') then
    return pg_catalog.jsonb_build_object('status','delivery_active');
  end if;

  select coalesce(pg_catalog.sum(amount_minor),0)::bigint, coalesce(pg_catalog.sum(tip_minor),0)::bigint
    into v_captured, v_captured_tip
  from app.payments
  where restaurant_id = v_restaurant and branch_id = v_branch and order_id = v_order_id and state = 'captured';
  v_obligation := case when v_captured > 0 or v_captured_tip > 0 or v_start_status in ('partially_paid','paid')
    then 'pending' else 'none' end;

  if exists (select 1 from pg_catalog.jsonb_array_elements(v_current.aggregate -> 'items') i(value)
    where i.value ->> 'status' = 'delivered')
  then return pg_catalog.jsonb_build_object('status','conflict'); end if;

  v_count := pg_catalog.jsonb_array_length(p_steps);
  if v_count < 1 then return pg_catalog.jsonb_build_object('status','conflict'); end if;
  v_authorization := pg_catalog.jsonb_build_object('approved', true, 'actorId', p_actor_id::text);

  begin
    for v_index in 1..v_count loop
      v_step := p_steps -> (v_index - 1);
      if pg_catalog.jsonb_typeof(v_step) <> 'object' or not app_private.jsonb_has_exact_keys(v_step, array['order','audit'])
      then raise exception 'CANCEL_ORDER_STEP_SHAPE'; end if;
      v_order := v_step -> 'order';
      v_audit := v_step -> 'audit';
      if pg_catalog.jsonb_typeof(v_order) <> 'object' or pg_catalog.jsonb_typeof(v_audit) <> 'object'
        or v_order ->> 'schemaVersion' <> '1' or v_audit ->> 'schemaVersion' <> '1'
        or v_audit ->> 'actorId' <> p_actor_id::text or v_audit ->> 'restaurantId' <> v_restaurant::text
        or v_audit ->> 'branchId' <> v_branch::text or v_audit ->> 'orderId' <> v_order_id::text
        or v_audit ->> 'deviceId' <> v_device::text or v_audit ->> 'occurredAt' <> p_command ->> 'occurredAt'
        or v_audit ->> 'reason' <> v_reason
        or v_audit -> 'authorization' is distinct from v_authorization
        or v_order ->> 'restaurantId' <> v_restaurant::text or v_order ->> 'branchId' <> v_branch::text
        or v_order ->> 'orderId' <> v_order_id::text
        or v_order ->> 'channel' <> v_current.aggregate ->> 'channel'
        or (v_order ->> 'tableId') is distinct from (v_current.aggregate ->> 'tableId')
        or v_order ->> 'currency' <> v_current.aggregate ->> 'currency'
        or v_order ->> 'timeZone' <> v_current.aggregate ->> 'timeZone'
        or pg_catalog.jsonb_typeof(v_order -> 'items') <> 'array'
        or pg_catalog.jsonb_array_length(v_order -> 'items')
          <> pg_catalog.jsonb_array_length(v_current.aggregate -> 'items')
      then raise exception 'CANCEL_ORDER_STEP_INVALID'; end if;
      v_step_event := (v_audit ->> 'eventId')::uuid;
      v_step_key := v_audit ->> 'idempotencyKey';
      if v_step_key is null or v_step_key <> pg_catalog.btrim(v_step_key)
        or pg_catalog.char_length(v_step_key) not between 1 and 200 or v_step_key ~ '[[:cntrl:]]'
      then raise exception 'CANCEL_ORDER_STEP_KEY'; end if;

      if v_index < v_count then
        -- A line already on the kitchen's screen: its own audit event and KDS correction.
        v_item_id := (v_audit ->> 'entityId')::uuid;
        select value into v_old_item from pg_catalog.jsonb_array_elements(v_current.aggregate -> 'items') i(value)
          where i.value ->> 'orderItemId' = v_item_id::text;
        select value into v_new_item from pg_catalog.jsonb_array_elements(v_order -> 'items') i(value)
          where i.value ->> 'orderItemId' = v_item_id::text;
        v_old_status := v_old_item ->> 'status';
        if v_audit ->> 'operation' <> 'order_item.state_changed' or v_audit ->> 'entityType' <> 'order_item'
          or v_audit ->> 'orderItemId' <> v_item_id::text or v_audit ->> 'to' <> 'cancelled'
          or v_old_item is null or v_new_item is null
          or v_old_status not in ('sent','preparing','ready') or v_audit ->> 'from' <> v_old_status
          or v_order ->> 'status' <> v_current.status
          or (v_order - 'items') <> (v_current.aggregate - 'items')
          or v_new_item ->> 'status' <> 'cancelled'
          or pg_catalog.jsonb_typeof(v_new_item -> 'cancellationAudit') <> 'object'
          or (v_old_item - 'status') <> (v_new_item - 'status' - 'cancellationAudit')
          or (select pg_catalog.jsonb_agg(i.value order by i.value ->> 'orderItemId')
              from pg_catalog.jsonb_array_elements(v_current.aggregate -> 'items') i(value)
              where i.value ->> 'orderItemId' <> v_item_id::text)
            is distinct from
            (select pg_catalog.jsonb_agg(i.value order by i.value ->> 'orderItemId')
              from pg_catalog.jsonb_array_elements(v_order -> 'items') i(value)
              where i.value ->> 'orderItemId' <> v_item_id::text)
          or v_new_item -> 'cancellationAudit' ->> 'eventId' <> v_step_event::text
          or v_new_item -> 'cancellationAudit' ->> 'idempotencyKey' <> v_step_key
          or v_new_item -> 'cancellationAudit' ->> 'from' <> v_old_status
          or v_new_item -> 'cancellationAudit' ->> 'actorId' <> p_actor_id::text
          or v_new_item -> 'cancellationAudit' ->> 'branchId' <> v_branch::text
          or v_new_item -> 'cancellationAudit' ->> 'deviceId' <> v_device::text
          or v_new_item -> 'cancellationAudit' ->> 'occurredAt' <> p_command ->> 'occurredAt'
          or v_new_item -> 'cancellationAudit' ->> 'reason' <> v_reason
          or v_new_item -> 'cancellationAudit' -> 'authorization' is distinct from v_authorization
        then raise exception 'CANCEL_ORDER_ITEM_STEP_INVALID'; end if;

        update app.orders set aggregate = v_order, version = version + 1,
          updated_at = pg_catalog.clock_timestamp(), updated_by = p_actor_id
        where restaurant_id = v_restaurant and branch_id = v_branch and id = v_order_id and version = v_current.version
        returning * into strict v_current;
        insert into app.order_audit_events(
          event_id, idempotency_key, restaurant_id, branch_id, order_id, actor_id, device_id,
          operation, entity_type, entity_id, expected_order_version, result_order_version,
          event_payload, result_order, occurred_at
        ) values (
          v_step_event, v_step_key, v_restaurant, v_branch, v_order_id, p_actor_id, v_device,
          'order_item.state_changed', 'order_item', v_item_id, v_current.version - 1, v_current.version,
          v_audit, v_order, v_occurred
        ) returning received_at into v_received;
        v_station := v_new_item -> 'snapshot' ->> 'stationId';
        if v_station is null or v_station <> pg_catalog.btrim(v_station)
          or pg_catalog.char_length(v_station) not between 1 and 64 or v_station ~ '[[:cntrl:]]'
        then raise exception 'KDS_EVENT_INVALID'; end if;
        insert into app_private.kds_branch_cursors(restaurant_id, branch_id, last_cursor)
          values (v_restaurant, v_branch, 0) on conflict do nothing;
        update app_private.kds_branch_cursors set last_cursor = last_cursor + 1
          where restaurant_id = v_restaurant and branch_id = v_branch returning last_cursor into strict v_cursor;
        insert into app.kds_events(event_id, restaurant_id, branch_id, cursor, order_id, order_item_id, station_id,
          operation, status, occurred_at, received_at)
        values (v_step_event, v_restaurant, v_branch, v_cursor, v_order_id, v_item_id, v_station,
          'order_item.status_changed', 'cancelled', v_occurred, v_received);
        v_kds_events := v_kds_events || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
          'schemaVersion', 1,
          'scope', pg_catalog.jsonb_build_object('restaurantId', v_restaurant::text, 'branchId', v_branch::text),
          'cursor', 'v1:' || v_cursor::text, 'eventId', v_step_event::text, 'orderId', v_order_id::text,
          'orderItemId', v_item_id::text, 'stationId', v_station,
          'operation', 'order_item.status_changed', 'status', 'cancelled',
          'occurredAt', pg_catalog.to_char(v_occurred at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
          'receivedAt', pg_catalog.to_char(v_received at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
      else
        -- The order event: every remaining line is pending (auto-cancelled by it) or already cancelled.
        select coalesce(pg_catalog.jsonb_agg(i.value ->> 'orderItemId' order by i.value ->> 'orderItemId'), '[]'::jsonb)
          into v_expected_pending
        from pg_catalog.jsonb_array_elements(v_current.aggregate -> 'items') i(value)
        where i.value ->> 'status' = 'pending';
        if exists (select 1 from pg_catalog.jsonb_array_elements(v_current.aggregate -> 'items') i(value)
          where i.value ->> 'status' not in ('pending','cancelled'))
          or v_step_event <> v_event or v_step_key <> v_key
          or v_audit ->> 'operation' <> 'order.state_changed' or v_audit ->> 'entityType' <> 'order'
          or v_audit ->> 'entityId' <> v_order_id::text
          or v_audit ->> 'from' <> v_start_status or v_audit ->> 'to' <> 'cancelled'
          or v_order ->> 'status' <> 'cancelled'
          or pg_catalog.jsonb_typeof(v_audit -> 'automaticallyCancelledOrderItemIds') <> 'array'
          or (select coalesce(pg_catalog.jsonb_agg(x.value order by x.value #>> '{}'), '[]'::jsonb)
              from pg_catalog.jsonb_array_elements(v_audit -> 'automaticallyCancelledOrderItemIds') x(value))
            <> v_expected_pending
          or (v_order - 'items' - 'status' - 'cancellationAudit') <> (v_current.aggregate - 'items' - 'status')
          or pg_catalog.jsonb_typeof(v_order -> 'cancellationAudit') <> 'object'
          or v_order -> 'cancellationAudit' ->> 'eventId' <> v_event::text
          or v_order -> 'cancellationAudit' ->> 'idempotencyKey' <> v_key
          or v_order -> 'cancellationAudit' ->> 'from' <> v_start_status
          or v_order -> 'cancellationAudit' ->> 'actorId' <> p_actor_id::text
          or v_order -> 'cancellationAudit' ->> 'branchId' <> v_branch::text
          or v_order -> 'cancellationAudit' ->> 'deviceId' <> v_device::text
          or v_order -> 'cancellationAudit' ->> 'occurredAt' <> p_command ->> 'occurredAt'
          or v_order -> 'cancellationAudit' ->> 'reason' <> v_reason
          or v_order -> 'cancellationAudit' -> 'authorization' is distinct from v_authorization
          -- Previously cancelled lines are untouched; pending ones become cancelled with this event's evidence.
          or exists (
            select 1 from pg_catalog.jsonb_array_elements(v_current.aggregate -> 'items') o(value)
            join pg_catalog.jsonb_array_elements(v_order -> 'items') n(value)
              on n.value ->> 'orderItemId' = o.value ->> 'orderItemId'
            where (o.value ->> 'status' = 'cancelled' and n.value is distinct from o.value)
              or (o.value ->> 'status' = 'pending' and (
                n.value ->> 'status' <> 'cancelled'
                or (o.value - 'status') <> (n.value - 'status' - 'cancellationAudit')
                or n.value -> 'cancellationAudit' ->> 'eventId' <> v_event::text
                or n.value -> 'cancellationAudit' ->> 'idempotencyKey' <> v_key
                or n.value -> 'cancellationAudit' ->> 'from' <> 'pending'
                or n.value -> 'cancellationAudit' ->> 'actorId' <> p_actor_id::text
                or n.value -> 'cancellationAudit' ->> 'branchId' <> v_branch::text
                or n.value -> 'cancellationAudit' ->> 'deviceId' <> v_device::text
                or n.value -> 'cancellationAudit' ->> 'occurredAt' <> p_command ->> 'occurredAt'
                or n.value -> 'cancellationAudit' ->> 'reason' <> v_reason
                or n.value -> 'cancellationAudit' -> 'authorization' is distinct from v_authorization))
          )
          or (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_order -> 'items') n(value)
              where n.value ->> 'status' <> 'cancelled') <> 0
        then raise exception 'CANCEL_ORDER_FINAL_STEP_INVALID'; end if;

        update app.orders set status = 'cancelled', aggregate = v_order, version = version + 1,
          updated_at = pg_catalog.clock_timestamp(), updated_by = p_actor_id
        where restaurant_id = v_restaurant and branch_id = v_branch and id = v_order_id and version = v_current.version
        returning * into strict v_current;
        insert into app.order_audit_events(
          event_id, idempotency_key, restaurant_id, branch_id, order_id, actor_id, device_id,
          operation, entity_type, entity_id, expected_order_version, result_order_version,
          event_payload, result_order, occurred_at
        ) values (
          v_event, v_key, v_restaurant, v_branch, v_order_id, p_actor_id, v_device,
          'order.state_changed', 'order', v_order_id, v_current.version - 1, v_current.version,
          v_audit, v_order, v_occurred
        );
      end if;
    end loop;
  exception when others then
    return pg_catalog.jsonb_build_object('status','conflict');
  end;

  insert into app.order_cancellations(
    restaurant_id, branch_id, order_id, event_id, from_status, result_version, reason, actor_id, device_id,
    occurred_at, refund_obligation_status, captured_minor, captured_tip_minor, currency
  ) values (
    v_restaurant, v_branch, v_order_id, v_event, v_start_status, v_current.version, v_reason, p_actor_id, v_device,
    v_occurred, v_obligation, v_captured, v_captured_tip, v_current.aggregate ->> 'currency'
  );

  v_result := pg_catalog.jsonb_build_object(
    'schemaVersion', 1,
    'scope', pg_catalog.jsonb_build_object('restaurantId', v_restaurant::text, 'branchId', v_branch::text),
    'status', 'saved',
    'order', v_current.aggregate,
    'version', v_current.version,
    'refundObligation', pg_catalog.jsonb_build_object(
      'status', v_obligation, 'capturedMinor', v_captured, 'capturedTipMinor', v_captured_tip,
      'currency', v_current.aggregate ->> 'currency'),
    'kdsEvents', v_kds_events
  );
  insert into app.order_command_events(
    restaurant_id, branch_id, order_id, actor_id, device_id, command_kind, event_id, idempotency_key,
    command_payload, result
  ) values (
    v_restaurant, v_branch, v_order_id, p_actor_id, v_device, 'cancel_order', v_event, v_key, p_command, v_result
  );
  return v_result;
end
$function$;

-- Reader of the "Canceladas" tab: cancelled orders (from order_cancellations) and closed captures (no_sale, from the
-- capture command journal), newest first, keyset page by (at desc, id). Branch scoped; read roles as the order tray.
-- It never derives money: orders carry their frozen aggregate and the recorded obligation; the API computes totals.
create function app_private.list_cancelled_work_items(p_actor_id uuid, p_request jsonb)
returns jsonb language plpgsql stable security definer set search_path = '' as $function$
declare
  v_restaurant uuid;
  v_branch uuid;
  v_limit integer;
  v_after_at timestamptz;
  v_after_id uuid;
  v_rows jsonb;
  v_next jsonb;
begin
  if p_actor_id is null
    or not app_private.jsonb_has_exact_keys(p_request, array['schemaVersion','scope','limit','after'])
    or not app_private.jsonb_has_exact_keys(p_request -> 'scope', array['restaurantId','branchId'])
    or p_request -> 'schemaVersion' is distinct from '1'::jsonb
    or pg_catalog.jsonb_typeof(p_request -> 'limit') is distinct from 'number'
    or not coalesce(p_request ->> 'limit' ~ '^[1-9][0-9]*$', false)
    or (p_request -> 'after' <> 'null'::jsonb and not app_private.jsonb_has_exact_keys(
      p_request -> 'after', array['at','id']))
  then return pg_catalog.jsonb_build_object('status','rejected'); end if;
  begin
    v_restaurant := (p_request #>> '{scope,restaurantId}')::uuid;
    v_branch := (p_request #>> '{scope,branchId}')::uuid;
    v_limit := (p_request ->> 'limit')::integer;
    if p_request -> 'after' <> 'null'::jsonb then
      v_after_at := (p_request #>> '{after,at}')::timestamptz;
      v_after_id := (p_request #>> '{after,id}')::uuid;
    end if;
  exception when invalid_text_representation or numeric_value_out_of_range
    or datetime_field_overflow or invalid_datetime_format then
    return pg_catalog.jsonb_build_object('status','rejected');
  end;
  if v_restaurant is null or v_branch is null or v_limit not between 1 and 100
    or (p_request -> 'after' <> 'null'::jsonb and (
      v_after_at is null or v_after_id is null
      or p_request #>> '{after,at}' is distinct from
        pg_catalog.to_char(v_after_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')))
  then return pg_catalog.jsonb_build_object('status','rejected'); end if;

  if not exists (
    select 1 from app.memberships m
    join app.branches b on b.restaurant_id = m.restaurant_id and b.id = m.branch_id
    join app.restaurants r on r.id = m.restaurant_id
    join app.membership_role_grants g on g.membership_id = m.id
    where m.user_id = p_actor_id and m.restaurant_id = v_restaurant and m.branch_id = v_branch
      and m.revoked_at is null and b.disabled_at is null and r.disabled_at is null and g.revoked_at is null
      and g.role_code in ('owner','admin','manager','supervisor','cashier','waiter','kitchen','viewer','auditor')
  ) then return pg_catalog.jsonb_build_object('status','denied'); end if;

  with merged as (
    select c.received_at as at, c.order_id as id, 'order'::text as kind, c.reason, c.actor_id,
      c.occurred_at, c.refund_obligation_status, c.captured_minor, c.captured_tip_minor, c.currency,
      c.from_status, o.version, o.channel, o.aggregate, frozen.snapshot,
      null::text as folio, null::text as fulfillment_channel, null::text as source_channel
    from app.order_cancellations c
    join app.orders o on o.restaurant_id = c.restaurant_id and o.branch_id = c.branch_id and o.id = c.order_id
    left join app.order_fulfillment_snapshots frozen
      on frozen.restaurant_id = o.restaurant_id and frozen.branch_id = o.branch_id and frozen.order_id = o.id
    where c.restaurant_id = v_restaurant and c.branch_id = v_branch
    union all
    select e.received_at, d.id, 'capture', e.reason, e.actor_id, e.occurred_at, null, null, null, null,
      null, null, null, null, null, d.folio, d.fulfillment_channel, d.source_channel
    from app.capture_command_events e
    join app.capture_drafts d on d.restaurant_id = e.restaurant_id and d.branch_id = e.branch_id
      and d.id = e.capture_draft_id and d.status = 'no_sale'
    where e.restaurant_id = v_restaurant and e.branch_id = v_branch and e.operation = 'capture.no_sale'
  ), page as materialized (
    select * from merged m
    where v_after_at is null or m.at < v_after_at or (m.at = v_after_at and m.id > v_after_id)
    order by m.at desc, m.id
    limit v_limit + 1
  ), numbered as (
    select page.*, row_number() over (order by at desc, id) as row_number from page
  )
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'kind', n.kind, 'id', n.id::text,
    'at', pg_catalog.to_char(n.at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'occurredAt', pg_catalog.to_char(n.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'reason', n.reason, 'actorId', n.actor_id::text,
    'refundObligationStatus', n.refund_obligation_status,
    'capturedMinor', n.captured_minor, 'capturedTipMinor', n.captured_tip_minor, 'currency', n.currency,
    'fromStatus', n.from_status, 'version', n.version, 'channel', n.channel,
    'order', n.aggregate, 'snapshot', n.snapshot,
    'folio', n.folio, 'fulfillmentChannel', n.fulfillment_channel, 'sourceChannel', n.source_channel
  ) order by n.at desc, n.id), '[]'::jsonb),
    (select pg_catalog.jsonb_build_object('at',
      pg_catalog.to_char(c.at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'), 'id', c.id::text)
      from numbered c where c.row_number = v_limit and exists (
        select 1 from numbered extra where extra.row_number = v_limit + 1))
  into v_rows, v_next
  from numbered n where n.row_number <= v_limit;

  return pg_catalog.jsonb_build_object('schemaVersion', 1,
    'scope', pg_catalog.jsonb_build_object('restaurantId', v_restaurant::text, 'branchId', v_branch::text),
    'items', v_rows, 'next', v_next);
end
$function$;

do $owner$
begin
  if not exists (select 1 from pg_catalog.pg_roles where rolname = 'postgres' and rolbypassrls)
    or not exists (select 1 from pg_catalog.pg_roles where rolname = 'app_api'
      and not rolsuper and not rolcreatedb and not rolcreaterole
      and not rolinherit and not rolreplication and not rolbypassrls)
  then raise exception using errcode = '55000', message = 'APP_API_ROLE_REJECTED'; end if;
end
$owner$;

alter function app_private.cancel_order(uuid,jsonb,jsonb) owner to postgres;
alter function app_private.list_cancelled_work_items(uuid,jsonb) owner to postgres;
revoke all on function app_private.cancel_order(uuid,jsonb,jsonb)
  from public, anon, authenticated, service_role, app_api;
revoke all on function app_private.list_cancelled_work_items(uuid,jsonb)
  from public, anon, authenticated, service_role, app_api;
grant execute on function app_private.cancel_order(uuid,jsonb,jsonb) to app_api;
grant execute on function app_private.list_cancelled_work_items(uuid,jsonb) to app_api;

comment on function app_private.cancel_order(uuid,jsonb,jsonb) is
  'Server-only, atomic whole-order cancellation (owner/admin/manager/supervisor): re-verifies the domain-computed steps, cancels sent lines with KDS corrections, blocks active deliveries (status delivery_active), records an immutable pending refund obligation when money was captured, with command-level idempotency.';
comment on function app_private.list_cancelled_work_items(uuid,jsonb) is
  'Server-only, Branch-scoped keyset page of cancelled orders (with recorded refund obligation) and no-sale captures for the Canceladas view; never derives money.';

commit;
